-- K7 vocab domains (W0). Copied from contracts/db/vocab_domains.sql at the freeze; later enum values go in a new
-- migration (ALTER DOMAIN ... DROP/ADD CONSTRAINT); tests/contracts/test_db.py checks the live domains.
CREATE DOMAIN sgw_run_mode AS text CHECK (VALUE IN ('live', 'replay', 'backfill', 'shadow', 'what_if'));
CREATE DOMAIN sgw_feed_mode AS text CHECK (VALUE IN ('live', 'replay', 'synthetic'));
CREATE DOMAIN sgw_scenario_mode AS text CHECK (VALUE IN ('REPLAY', 'EXERCISE'));
CREATE DOMAIN sgw_crew_status AS text CHECK (VALUE IN ('available', 'staged', 'enroute', 'onsite', 'blocked', 'done', 'off_shift'));
CREATE DOMAIN sgw_block_reason AS text CHECK (VALUE IN ('safety_hold', 'road_closed', 'wind_above_bucket_limit', 'awaiting_material', 'awaiting_switching'));
CREATE DOMAIN sgw_quality AS text CHECK (VALUE IN ('good', 'suspect', 'bad', 'missing'));
CREATE DOMAIN sgw_finality AS text CHECK (VALUE IN ('provisional', 'confirmed', 'retracted'));
CREATE DOMAIN sgw_ui_severity AS text CHECK (VALUE IN ('critical', 'severe', 'elevated', 'advisory', 'normal', 'unknown_stale'));
CREATE DOMAIN sgw_classification AS text CHECK (VALUE IN ('C0', 'C1', 'C2', 'C3', 'C3-N', 'C4', 'CX'));
CREATE DOMAIN sgw_trust AS text CHECK (VALUE IN ('system', 'verified_internal', 'internal_free_text', 'external'));
CREATE DOMAIN sgw_tier AS text CHECK (VALUE IN ('T0', 'T1', 'T2', 'T3', 'T4'));
CREATE DOMAIN sgw_proposal_state AS text CHECK (VALUE IN ('draft', 'proposed', 'in_review', 'approved', 'rejected', 'withdrawn', 'expired', 'escalated', 'executed'));
CREATE DOMAIN sgw_effect_state AS text CHECK (VALUE IN ('queued', 'sent', 'delivery_unknown', 'acknowledged'));
CREATE DOMAIN sgw_kill_level AS text CHECK (VALUE IN ('K0', 'K1', 'K2', 'K3', 'K4'));
CREATE DOMAIN sgw_degraded_mode AS text CHECK (VALUE IN ('M0', 'M1', 'M2', 'M3', 'M4'));
CREATE DOMAIN sgw_domain AS text CHECK (VALUE IN ('electric', 'water'));
CREATE DOMAIN sgw_approval_function AS text CHECK (VALUE IN ('command', 'operations', 'planning', 'logistics', 'water_operations', 'compliance', 'executive', 'audit', 'platform', 'data', 'communications'));
CREATE DOMAIN sgw_risk_band AS text CHECK (VALUE IN ('very_low', 'low', 'moderate', 'high', 'very_high'));
CREATE DOMAIN sgw_clock_kind AS text CHECK (VALUE IN ('rule_deadline', 'model_estimate'));
CREATE DOMAIN sgw_no_regret_verdict AS text CHECK (VALUE IN ('act_now', 'wait_for_next_advisory', 'n/a', 'decide_now'));
CREATE DOMAIN sgw_module AS text CHECK (VALUE IN ('map', 'decisions', 'forecast', 'crews', 'water', 'ask', 'brief', 'after_action', 'health', 'readiness', 'admin'));
CREATE DOMAIN sgw_decision_step AS text CHECK (VALUE IN ('D1', 'D2', 'D3', 'D4', 'D5'));
CREATE DOMAIN sgw_action_type AS text CHECK (VALUE IN ('set_event_type', 'preposition_crews', 'reoptimise_within_envelope', 'stage_crews_small', 'mutual_aid_request', 'cross_domain_priority', 'boil_water_notice', 'publish_global_etr', 'work_order_draft', 'sitrep_draft'));
CREATE DOMAIN sgw_initiator_kind AS text CHECK (VALUE IN ('person', 'system_rule', 'agent'));
CREATE DOMAIN sgw_approval_decision AS text CHECK (VALUE IN ('approve', 'reject', 'break_glass', 'cosign'));
CREATE DOMAIN sgw_commitment_state AS text CHECK (VALUE IN ('on_track', 'at_risk', 'drifted', 'met', 'missed', 'cancelled'));
CREATE DOMAIN sgw_webhook_delivery_state AS text CHECK (VALUE IN ('pending', 'delivered', 'retrying', 'failed', 'disabled'));
CREATE DOMAIN sgw_api_scope AS text CHECK (VALUE IN ('decisions:read', 'clocks:read', 'commitments:read', 'webhooks:manage'));
CREATE DOMAIN sgw_number_label AS text CHECK (VALUE IN ('F', 'C', 'A', 'U', 'P', 'S'));
CREATE DOMAIN sgw_number_kind AS text CHECK (VALUE IN ('fact', 'computed', 'assumption', 'policy'));
CREATE DOMAIN sgw_eval_split AS text CHECK (VALUE IN ('dev', 'heldout_family_b', 'real_loso', 'ladi_reference'));
CREATE DOMAIN sgw_model_alias AS text CHECK (VALUE IN ('sonnet', 'haiku', 'opus'));
CREATE DOMAIN sgw_effort AS text CHECK (VALUE IN ('low', 'medium', 'high', 'xhigh', 'max'));
